// Une fois par heure, l'agent signale qu'il est en marche (pour le tableau de pilotage).
const d = new Date();
if (d.getMinutes() !== 0 || d.getSeconds() >= 20) return [];
return [{ json: { agent: 'D-analyse', debut: d.toISOString(), fin: d.toISOString(), statut: 'vide', entrees: 0, sorties: 0, details: { battement: true } } }];

// ===== RÉGLAGES =====
const MODELE = 'gpt-4o-mini';   // modèle OpenAI utilisé pour l'analyse (128 000 jetons de contexte)
const MAX = 300000;             // caractères lus au maximum (avis + dossier), soit environ 80 000 jetons
// ====================
const a = $('Lire la file').first().json;
const c = $('Lire le profil').all().map(i => i.json).find(x => x && x.id) || {};

// 1. Résultat de la collecte (avis officiel + DCE), si elle a eu lieu
const sortie = $('Collecter l\'avis et le DCE').first().json || {};
let col = {};
try { col = JSON.parse(String(sortie.stdout || '').trim() || '{}'); }
catch (e) { col = { erreurs: ['Réponse du script de collecte illisible : ' + String(sortie.stdout || '').slice(0, 150)] }; }
const erreurCollecte = sortie.error ? String(sortie.error.message || sortie.error).slice(0, 200)
  : (sortie.stderr && !sortie.stdout ? String(sortie.stderr).slice(0, 200) : null);
const dce = col.dce || {};

// 2. Pièces dans l'ordre utile : règlement, CCAP, acte d'engagement, CCTP, le reste
const rang = s => { const t = (s.match(/FICHIER : ([^\n]*)/) || [, ''])[1].toLowerCase();
  return /r[eè]glement|\brc\b|_rc|rc[_ .-]/.test(t) ? 0 : /ccap/.test(t) ? 1 : /\bae\b|acte|engagement/.test(t) ? 2 : /cctp/.test(t) ? 3 : /bpu|dpgf|dqe/.test(t) ? 5 : 4; };
const pieces = [String(col.dce_texte || ''), String(a.texte || '')].join('\n')
  .split(/(?=\n*===== FICHIER : )/).filter(s => s.trim()).sort((x, y) => rang(x) - rang(y)).join('\n');
const avis = col.avis?.texte ? `===== AVIS OFFICIEL (${col.avis.source === 'boamp' ? 'BOAMP' : 'page de la consultation'}) =====\n${col.avis.texte}\n` : '';
let texte = (avis + '\n' + pieces).replace(/[ \t]+/g, ' ').trim();
const coupe = texte.length > MAX; if (coupe) texte = texte.slice(0, MAX);

// 3. Ce que l'agent a réellement lu (affiché au client avec l'analyse)
const sources = {
  avis: col.avis?.texte ? (col.avis.source === 'boamp' ? 'BOAMP' : 'page de la consultation') : null,
  avis_url: col.avis?.url || a.avis_url || null,
  dce_demande: !!dce.demande, dce_statut: dce.statut || null, plateforme: dce.plateforme || null, dce_raison: dce.raison || erreurCollecte || null,
  fichiers: (dce.fichiers || []).slice(0, 80),
  pdf_client: !!a.texte, caracteres: texte.length, coupe,
  erreurs: [...(col.erreurs || []), ...(erreurCollecte ? [erreurCollecte] : [])].slice(0, 6)
};
const seulementAvis = !pieces.trim();
const sansTexte = texte.replace(/\s/g, '').length < 300;

const consignes = `Tu es un expert des marchés publics français (code de la commande publique), conseiller d'une PME qui hésite à répondre.
Tu analyses en profondeur les documents de consultation fournis et tu rends une analyse COMPLÈTE, CONCRÈTE et CLAIRE, rédigée pour un chef d'entreprise (pas de jargon inutile, phrases courtes).

ENTREPRISE QUI ANALYSE
Nom : ${c.entreprise || 'non précisé'}
Activité : ${c.metiers || 'non précisée'} ${c.mots_cles ? '(' + String(c.mots_cles).slice(0, 300) + ')' : ''}
Présentation : ${String(c.description || 'non renseignée').slice(0, 1200)}
Qualifications et certifications : ${c.qualifications || 'non renseignées'}
Effectif : ${c.effectif || 'non précisé'} ; chiffre d'affaires : ${c.ca_annuel || 'non précisé'}
Zone d'intervention : départements ${c.departements || 'non précisés (toute la France)'}
Montant minimum visé : ${c.montant_min ? c.montant_min + ' € HT' : 'aucun'}
Marchés publics déjà remportés : ${String(c.marches_gagnes || 'aucun connu').slice(0, 1500)}

DOCUMENTS LUS
${seulementAvis ? "Seul l'avis officiel est disponible : le règlement de consultation, le CCAP et le CCTP n'ont PAS été lus. Dis-le clairement, reste prudent dans l'avis final et liste ce qu'il faudra vérifier dans le DCE." : "Avis et pièces du dossier de consultation (chaque pièce commence par « ===== FICHIER : nom »)."}${coupe ? ' Le dossier était très long : la fin a été coupée.' : ''}

RÈGLES
- Lis tout. Sois exhaustif sur les pièces à fournir, les conditions de participation, les critères et les clauses financières.
- N'invente rien. Si une information est absente des documents, écris « Non précisé dans les documents lus ».
- Cite la source à chaque fois que possible dans "ref" (ex. « RC art. 5.3 », « CCAP art. 14.1 », « Avis, section 5 »).
- Dates au format « vendredi 4 décembre 2026 à 12 h » quand le jour et l'heure sont connus.
- Compare chaque condition de participation au profil de l'entreprise : "conforme" si le profil le confirme, "manquant" si le profil montre que ce n'est pas rempli, sinon "à vérifier".
- Donne un conseil pratique et précis pour chaque critère de notation (ce que l'acheteur attend dans le mémoire technique, comment marquer des points).
- "decision" : "On y va" si l'entreprise est clairement en mesure de répondre et a de bonnes chances ; "À étudier" si c'est possible mais avec des points à lever ; "On passe" si hors métier, hors capacité ou trop risqué. Ne promets jamais que l'entreprise remportera ou est éligible.
- Plan d'action : étapes datées à rebours depuis la date limite (visite, questions, candidature, mémoire, prix, dépôt).

Réponds UNIQUEMENT avec un objet JSON valide, exactement de cette forme (listes aussi longues que nécessaire) :
{"version":2,
"synthese":{"decision":"On y va|À étudier|On passe","adequation":"forte|moyenne|faible","en_bref":"3 à 5 phrases : ce que l'acheteur veut, l'enjeu, ce qui compte pour gagner","raison":"pourquoi cette décision pour CETTE entreprise","points_forts":[""],"points_bloquants":[""]},
"identite":{"objet":"","acheteur":"","reference":"","procedure":"","type_marche":"","forme":"marché ordinaire, accord-cadre à bons de commande (avec minimum/maximum)…","lieu":"","duree":"","reconduction":"","montant":"","variantes":"","groupement_sous_traitance":""},
"calendrier":[{"etape":"","date":"","detail":"","ref":""}],
"lots":[{"numero":"","intitule":"","montant":"","pour_vous":"oui|partiel|non","pourquoi":""}],
"conditions":[{"exigence":"","detail":"","votre_situation":"conforme|à vérifier|manquant","ref":""}],
"criteres":[{"critere":"","poids":0,"sous_criteres":[""],"conseil":""}],
"pieces_candidature":[{"piece":"","ref":"","conseil":""}],
"pieces_offre":[{"piece":"","ref":"","conseil":""}],
"finances":[{"sujet":"Avance, Retenue de garantie, Délai de paiement, Prix (forme, révision), Pénalités, Garanties et assurances…","detail":"","ref":""}],
"technique":[{"point":"","detail":"","ref":""}],
"risques":[{"niveau":"élevé|moyen|faible","point":"","explication":"","ref":""}],
"questions_acheteur":[""],
"plan_action":[{"quand":"","action":""}],
"manquants":[""]}
"poids" est un nombre (pourcentage). "calendrier" contient au moins : date limite de remise, visite (ou « pas de visite »), date limite des questions, durée de validité des offres, démarrage prévu.`;

return [{ json: { debut: new Date().toISOString(), modele: MODELE, coupe, taille: texte.length, sansTexte, seulementAvis, sources,
  openai: { model: MODELE, temperature: 0.2, max_tokens: 9000, response_format: { type: 'json_object' },
    messages: [{ role: 'system', content: consignes }, { role: 'user', content: 'DOCUMENTS DE LA CONSULTATION :\n' + texte }] } } }];

const a = $('Lire la file').first().json;
const c = $('Lire le profil').all().map(i => i.json).find(x => x && x.id) || {};
const prep = $('Préparer l\'analyse').first().json;
const r = prep.sansTexte ? {} : ($input.first().json || {});
const brut = String(r.choices?.[0]?.message?.content || '');
let analyse = null;
try { analyse = JSON.parse(brut.replace(/```json|```/g, '').trim()); } catch (e) { const m = brut.match(/\{[\s\S]*\}/); if (m) { try { analyse = JSON.parse(m[0]); } catch (e2) {} } }
const ok = !!(analyse && (analyse.synthese || analyse.identite));
if (ok) { analyse.version = 2; analyse.sources = prep.sources; }
const s = prep.sources || {};

// Message affiché au-dessus de l'analyse : ce qui a été lu, et ce qui manque
const lus = (s.fichiers || []).filter(f => f.lu).length, nonLus = (s.fichiers || []).filter(f => !f.lu).length;
const morceaux = [];
if (s.avis) morceaux.push('avis officiel (' + s.avis + ')');
if (lus) morceaux.push(`dossier de consultation récupéré sur ${s.plateforme || 'la plateforme'} (${lus} pièce${lus > 1 ? 's' : ''} lue${lus > 1 ? 's' : ''}${nonLus ? `, ${nonLus} non lisible${nonLus > 1 ? 's' : ''}` : ''})`);
if (s.pdf_client) morceaux.push('les PDF que vous avez déposés');
let message = morceaux.length ? 'Documents lus : ' + morceaux.join(', ') + '.' : null;
if (s.dce_demande && !lus) message = (message ? message + ' ' : '') + 'Le dossier de consultation n\'a pas pu être récupéré automatiquement' + (s.dce_raison ? ' : ' + s.dce_raison.replace(/\.$/, '') : '') + '. Déposez les PDF du dossier pour une analyse complète.';
if (prep.coupe) message = (message ? message + ' ' : '') + 'Dossier très long : la fin n\'a pas pu être lue.';

const fin = new Date().toISOString();
const tentatives = Number(a.tentatives || 0);
const reessai = !ok && !prep.sansTexte && tentatives < 1;   // premier échec de l'IA : on relance une fois automatiquement
const echec = prep.sansTexte
  ? "Aucun document n'a pu être lu pour cette offre" + (s.dce_raison ? ' : ' + s.dce_raison.replace(/\.$/, '') : '') + ". Ouvrez l'avis, téléchargez le dossier de consultation et déposez les PDF ici."
  : r.error ? "Le service d'analyse ne répond pas pour le moment. Relancez l'analyse dans quelques minutes." : "L'analyse n'a pas pu être mise en forme. Relancez-la, ou envoyez le dossier par email.";
const objet = String(analyse?.identite?.objet || a.avis_objet || 'Dossier analysé').slice(0, 300);
const maj = reessai ? { statut: 'en_attente', tentatives: tentatives + 1, message: null }
  : ok ? { statut: 'terminee', resultat: analyse, objet, decision: String(analyse.synthese?.decision || '').slice(0, 50), texte: null, message, termine_le: fin }
  : { statut: 'erreur', texte: null, termine_le: fin, message: echec };
const raison = prep.sansTexte ? 'aucun document lu : ' + (s.dce_raison || (s.erreurs || []).join(' ; ') || 'collecte vide')
  : String(r.error?.message || r.error || (brut ? 'réponse illisible : ' + brut.slice(0, 200) : 'réponse vide')).slice(0, 400);
return [{ json: { ok, reessai, prevenir: !ok && !reessai, id: a.id, maj, email: c.email, entreprise: c.entreprise, analyse, raison,
  journal: { agent: 'D-analyse', debut: prep.debut, fin, statut: ok ? 'ok' : 'erreur', entrees: 1, sorties: ok ? 1 : 0,
             details: { caracteres: prep.taille, coupe: prep.coupe, modele: prep.modele, decision: ok ? analyse.synthese?.decision : null,
                        mode: a.mode || 'pdf', avis: s.avis, dce: s.dce_statut, plateforme: s.plateforme, pieces_lues: lus,
                        jetons: r.usage?.total_tokens || null },
             message: ok ? (s.dce_demande && !lus ? 'DCE non récupéré (' + (s.plateforme || '?') + ') : ' + String(s.dce_raison || '').slice(0, 200) : null)
               : (reessai ? 'Échec, nouvel essai automatique : ' : 'Échec définitif : ') + raison.slice(0, 250) } } }];

// Email récapitulatif : l'essentiel, puis un lien vers l'analyse complète dans l'espace client.
const j = $('Lire l\'analyse').first().json;
const a = j.analyse || {};
const sy = a.synthese || {}, id = a.identite || {};
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const LOGO = 'https://lumen-marches.pages.dev/logo-signature.png?v=2';
const ESPACE = 'https://lumen-marches.pages.dev/tableau.html';
const d = String(sy.decision || '').toLowerCase();
const [fond, texteC] = /pass/.test(d) ? ['#FDEEEE', '#9B2C2C'] : /tudier/.test(d) ? ['#FEF0CC', '#7A5400'] : ['#E7F6EC', '#1F7A3F'];
const liste = (l, f) => (l || []).slice(0, 4).map(f).join('');
const ligne = (k, v) => v ? `<tr><td style="padding:4px 0;color:#6B7280;width:150px;vertical-align:top;">${esc(k)}</td><td style="padding:4px 0;color:#171A21;font-weight:600;">${esc(v)}</td></tr>` : '';
const dates = liste(a.calendrier, x => ligne(x.etape, x.date + (x.detail ? ' (' + x.detail + ')' : '')));
const risques = liste((a.risques || []).filter(x => /lev|moy/i.test(x.niveau || '')), x => `<li style="margin-bottom:6px;"><b>${esc(x.point)}</b> : ${esc(x.explication)}</li>`);
const bloquants = liste(sy.points_bloquants, x => `<li style="margin-bottom:6px;">${esc(x)}</li>`);
const html = `<!doctype html><html><body style="margin:0;padding:0;background:#F6F7F9;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#F6F7F9;padding:28px 0;"><tr><td align="center">
<table role="presentation" width="640" cellpadding="0" cellspacing="0" style="background:#FFFFFF;border-radius:14px;overflow:hidden;border:1px solid #E6E8EC;">
<tr><td style="padding:22px 32px;border-bottom:1px solid #E6E8EC;"><img src="${LOGO}" width="180" height="29" alt="Lumen Marchés" style="display:block;border:0;width:180px;height:29px;"></td></tr>
<tr><td style="padding:28px 32px 8px;">
  <p style="margin:0 0 4px;font-size:12px;font-weight:700;color:#2350C4;text-transform:uppercase;letter-spacing:.04em;">Analyse de dossier</p>
  <p style="margin:0 0 4px;font-size:17px;font-weight:700;color:#171A21;line-height:1.4;">${esc(id.objet)}</p>
  <p style="margin:0 0 18px;font-size:14px;color:#6B7280;">${esc(id.acheteur)}</p>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${fond};border-radius:10px;margin-bottom:18px;"><tr><td style="padding:16px 18px;">
    <p style="margin:0 0 6px;font-size:13px;font-weight:700;color:${texteC};text-transform:uppercase;letter-spacing:.03em;">Notre avis : ${esc(sy.decision)}</p>
    <p style="margin:0;font-size:14px;color:#171A21;line-height:1.55;">${esc(sy.raison)}</p></td></tr></table>
  <p style="margin:0 0 18px;font-size:14px;color:#171A21;line-height:1.6;">${esc(sy.en_bref)}</p>
  ${dates ? `<p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#171A21;">Dates clés</p><table role="presentation" cellpadding="0" cellspacing="0" style="font-size:13px;width:100%;margin-bottom:18px;">${dates}</table>` : ''}
  ${bloquants ? `<p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#171A21;">Points à lever</p><ul style="margin:0 0 18px;padding-left:18px;font-size:13px;color:#171A21;line-height:1.5;">${bloquants}</ul>` : ''}
  ${risques ? `<p style="margin:0 0 6px;font-size:14px;font-weight:700;color:#171A21;">Principaux risques</p><ul style="margin:0 0 18px;padding-left:18px;font-size:13px;color:#171A21;line-height:1.5;">${risques}</ul>` : ''}
  <table role="presentation" cellpadding="0" cellspacing="0" style="margin:6px 0 22px;"><tr><td style="border-radius:8px;background:#2350C4;">
    <a href="${ESPACE}" style="display:inline-block;padding:13px 26px;font-size:14px;font-weight:700;color:#FFFFFF;text-decoration:none;border-radius:8px;">Voir l'analyse complète</a></td></tr></table>
  <p style="margin:0 0 18px;font-size:13px;color:#6B7280;line-height:1.5;">Dans votre espace : conditions de participation comparées à votre profil, critères de notation avec conseils, pièces à fournir à cocher, clauses financières, exigences techniques, questions à poser à l'acheteur et plan d'action daté.</p>
  ${j.maj?.message ? `<p style="margin:0 0 18px;font-size:12px;color:#6B7280;">${esc(j.maj.message)}</p>` : ''}
</td></tr>
<tr><td style="background:#F6F7F9;padding:16px 32px;border-top:1px solid #E6E8EC;"><p style="margin:0;font-size:12px;color:#6B7280;">Analyse produite par une IA : vérifiez toujours les dates et les pièces dans le règlement de consultation avant de déposer votre offre. L'équipe Lumen, lumeniaindustrie@gmail.com</p></td></tr>
</table></td></tr></table></body></html>`;
return [{ json: { to: j.email, subject: `Analyse : ${String(id.objet || 'votre dossier').slice(0, 80)} (${sy.decision || 'avis'})`, html } }];

const EMAIL_ADMIN = 'marinsauzay991@gmail.com';   // qui est prévenu quand une analyse échoue
const j = $('Lire l\'analyse').first().json;
const esc = s => String(s ?? '').replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const sortie = [{ json: { to: EMAIL_ADMIN, subject: `⚠️ Analyse échouée pour ${j.entreprise || 'un client'}`,
  html: `<div style="font-family:Arial,sans-serif;font-size:15px"><p>L'agent D n'a pas réussi à analyser le dossier n° ${j.id} de <b>${esc(j.entreprise)}</b> (${esc(j.email)}), même après un nouvel essai.</p><p>Raison : ${esc(j.raison)}</p><p>Le client voit un message d'échec dans son espace et a reçu un email. Pense à le recontacter.</p></div>` } }];
if (j.email) sortie.push({ json: { to: j.email, subject: "Votre analyse de dossier n'a pas abouti",
  html: `<div style="font-family:Arial,sans-serif;font-size:15px;color:#1a2433"><p>Bonjour,</p><p>Notre agent n'a pas réussi à analyser le dossier que vous avez déposé. Nous sommes prévenus et revenons vers vous rapidement.</p><p>En attendant, vous pouvez relancer l'analyse depuis votre espace, ou nous envoyer le dossier à lumeniaindustrie@gmail.com.</p><p>L'équipe Lumen<br>06 50 93 85 52</p></div>` } });
return sortie;

// ===== RÉGLAGE =====
// Emplacement du script de collecte sur ce PC (même dossier que les scrapers E1 à E8)
const SCRIPT = 'C:\\Users\\marin_3s4sfng\\Desktop\\Projet\\Lumenmarket\\Lument_agents\\D-analyse\\dce-collecte.js';
// ===================
// Quand le dossier est lié à une offre (bouton « Analyser », ou PDF déposés depuis une offre),
// le script va lire l'avis officiel, et en mode « auto » télécharger aussi le DCE.
// Les valeurs viennent du site : elles sont vérifiées puis passées encodées en base64,
// jamais telles quelles dans la ligne de commande.
const a = $('Lire la file').first().json;
const url = /^https?:\/\/[^\s"'<>`]{1,1000}$/.test(String(a.avis_url || '')) ? String(a.avis_url) : '';
const id = /^[A-Za-z0-9._:-]{1,120}$/.test(String(a.avis_id || '')) ? String(a.avis_id) : '';
const besoin = !!(url || id);
const json = JSON.stringify({ avis_id: id, url, objet: String(a.avis_objet || '').slice(0, 300), dce: a.mode === 'auto' && !a.texte });
const arg = typeof Buffer !== 'undefined' ? Buffer.from(json, 'utf8').toString('base64') : btoa(unescape(encodeURIComponent(json)));
if (!/^[A-Za-z0-9+/=]+$/.test(arg)) throw new Error('Encodage inattendu de l\'argument de collecte.');
return [{ json: { besoin, commande: besoin ? `node "${SCRIPT}" ${arg}` : 'echo {}' } }];
